import { mergeRefs } from '@react-aria/utils';
import { useRef, useState, useCallback, useLayoutEffect } from 'react';
import { flushSync } from 'react-dom';

const EXITING_SELECTOR = '[data-exiting="true"]';
const animationDurationMs = element => {
  const durations = getComputedStyle(element).animationDuration.split(",").map(part => {
    const value = part.trim();
    const amount = Number.parseFloat(value);
    if (Number.isNaN(amount)) return 0;
    return value.endsWith("ms") ? amount : amount * 1000;
  });
  return Math.max(0, ...durations);
};
const hasAnimationName = element => getComputedStyle(element).animationName.split(",").some(name => {
  const value = name.trim().replaceAll('"', "");
  return value !== "" && value !== "none";
});

/** The overlay and its exiting parts, e.g. a modal backdrop and its container. */
const exitingElements = element => [element, ...element.querySelectorAll(EXITING_SELECTOR)];

/** Longest exit animation on the overlay or an exiting part, in ms. */
const exitAnimationDuration = element => Math.max(0, ...exitingElements(element).map(node => hasAnimationName(node) ? animationDurationMs(node) : 0));
const isExitingTarget = (element, target) => target instanceof Element && (target === element || element.contains(target) && target.matches(EXITING_SELECTOR));
const runningExitAnimations = element => {
  if (typeof element.getAnimations !== "function" || typeof CSSAnimation === "undefined") {
    return [];
  }
  return element.getAnimations({
    subtree: true
  }).filter(animation => {
    return animation instanceof CSSAnimation && isExitingTarget(element, animation.effect?.target) && (animation.playState === "running" || String(animation.playState) === "pending");
  });
};

/**
 * Keeps an overlay mounted until its close animation is actually running.
 *
 * WebKit leaves a new CSS animation `pending` in the layout effect where React Aria
 * looks for `playState === "running"`, then unmounts. Holding `isExiting` lets the
 * animation paint. With no stylesheet animation, release through a normal setState.
 * After the animation ends, fill mode `none` would paint opacity 1 again, so pin it
 * and unmount before that frame.
 */
const useOverlayExitHold = (isOpen, {
  enabled = true,
  prepare,
  ref: forwardedRef
} = {}) => {
  const elementRef = useRef(null);
  const pinnedOpacity = useRef(new Map());
  const [isExiting, setIsExiting] = useState(false);
  const [prevOpen, setPrevOpen] = useState(isOpen);
  let exiting = isExiting;
  if (isOpen !== prevOpen) {
    setPrevOpen(isOpen);
    exiting = enabled && isOpen === false;
    if (exiting !== isExiting) setIsExiting(exiting);
  } else if ((!enabled || isOpen) && isExiting) {
    setIsExiting(false);
    exiting = false;
  }
  const ref = useCallback(
  // With multiple refs, mergeRefs always returns a callback, including its cleanup.
  node => mergeRefs(elementRef, forwardedRef)(node), [forwardedRef]);
  const endExit = useCallback(() => setIsExiting(false), []);
  useLayoutEffect(() => {
    // The caller may release its retention without changing isOpen.
    if (!elementRef.current) {
      pinnedOpacity.current.clear();
      return;
    }
    if (!isOpen) return;

    // A caller can retain the DOM with isExiting after our hold ends. Restore
    // those nodes before reopening, without overwriting a new consumer style.
    for (const [node, {
      priority,
      value
    }] of pinnedOpacity.current) {
      if (node.style.opacity === "0") {
        if (value) node.style.setProperty("opacity", value, priority);else node.style.removeProperty("opacity");
      }
    }
    pinnedOpacity.current.clear();
  });
  useLayoutEffect(() => {
    const element = elementRef.current;
    if (!exiting || !element) return;
    prepare?.(element);
    let settled = false;
    // Inside the layout effect, setState is already flushed before paint.
    const finish = () => {
      if (settled) return;
      settled = true;
      endExit();
    };
    // After the animation ends the fill is `none`, so computed opacity is already 1.
    // Pin it and unmount before that frame is painted.
    const finishBeforePaint = () => {
      if (settled) return;
      settled = true;
      for (const node of exitingElements(element)) {
        pinnedOpacity.current.set(node, {
          priority: node.style.getPropertyPriority("opacity"),
          value: node.style.opacity
        });
        node.style.opacity = "0";
      }
      flushSync(endExit);
    };
    const waitForAnimations = animations => {
      if (animations.length === 0) {
        finish();
        return;
      }
      void Promise.all(animations.map(animation => animation.finished)).then(finishBeforePaint, finishBeforePaint);
    };
    const current = runningExitAnimations(element);
    if (current.length > 0) {
      waitForAnimations(current);
      return () => {
        settled = true;
      };
    }
    const duration = exitAnimationDuration(element);

    // No stylesheet animation (jsdom, reduced motion). Release in this layout pass.
    if (duration === 0) {
      finish();
      return;
    }

    // WebKit has already applied the animation name, but getAnimations() still
    // reports nothing until the next frame. Hold until it is running, or until
    // its duration elapses if it never starts.
    const onAnimationDone = event => {
      if (!isExitingTarget(element, event.target)) return;
      if (runningExitAnimations(element).length > 0) return;
      finishBeforePaint();
    };
    element.addEventListener("animationend", onAnimationDone);
    element.addEventListener("animationcancel", onAnimationDone);
    const timeout = window.setTimeout(finishBeforePaint, duration + 50);
    const frame = window.requestAnimationFrame(() => {
      const next = runningExitAnimations(element);
      if (next.length === 0) return;
      window.clearTimeout(timeout);
      waitForAnimations(next);
    });
    return () => {
      settled = true;
      element.removeEventListener("animationend", onAnimationDone);
      element.removeEventListener("animationcancel", onAnimationDone);
      window.clearTimeout(timeout);
      window.cancelAnimationFrame(frame);
    };
  }, [endExit, exiting, prepare]);
  return {
    isExiting: exiting,
    ref
  };
};

/** Same open-state choice as React Aria: local `isOpen` wins, otherwise the trigger state. */
const resolveOverlayOpen = (isOpen, defaultOpen, state) => {
  if (isOpen != null || defaultOpen != null || !state) return isOpen;
  return state.isOpen;
};

export { resolveOverlayOpen, useOverlayExitHold };
